#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) adj[e[0]].push_back((int)e[1]);
    vector<int> indeg(n + 1, 0);
    for (const vector<long long>& e : edges) indeg[e[1]]++;
    vector<int> queue;
    for (int v = 1; v <= n; v++) {
        if (indeg[v] == 0) queue.push_back(v);
    }
    for (size_t i = 0; i < queue.size(); i++) {
        for (int v : adj[queue[i]]) {
            indeg[v]--;
            if (indeg[v] == 0) queue.push_back(v);
        }
    }
    cout << ((long long)queue.size() == n ? "yes" : "no") << "\n";

    return 0;
}

